import { prepareTopologyRenderFrame } from "./renderPipeline.js";
import { renderTopologyGridMarkup } from "./TopologyGridRenderer.js";
import { createTopologyTransitionController } from "./topologyTransition.js";
const svgNamespace = "http://www.w3.org/2000/svg";
function createContentLayer(sceneGrid, name) {
    const layer = document.createElementNS(svgNamespace, "g");
    layer.setAttribute("data-topology-dataset-layer", name);
    sceneGrid.append(layer);
    return layer;
}
function clearLayer(layer) {
    while (layer.firstChild)
        layer.firstChild.remove();
}
function appendRenderedContent(layer, markup) {
    clearLayer(layer);
    const parsed = document.createElementNS(svgNamespace, "svg");
    parsed.innerHTML = markup;
    const connectorGroup = parsed.querySelector(".grid-connectors");
    const occupantGroup = parsed.querySelector(".grid-occupants");
    if (connectorGroup)
        layer.append(connectorGroup);
    if (occupantGroup)
        layer.append(occupantGroup);
}
export function createTopologyDatasetTransition({ sceneGrid, cells, radius, connectorRouting = "straight", duration = 1700, reducedMotion = false, }) {
    const existingConnectors = sceneGrid.querySelector(".grid-connectors");
    const existingOccupants = sceneGrid.querySelector(".grid-occupants");
    const currentLayer = createContentLayer(sceneGrid, "current");
    const incomingLayer = createContentLayer(sceneGrid, "incoming");
    if (existingConnectors)
        currentLayer.append(existingConnectors);
    if (existingOccupants)
        currentLayer.append(existingOccupants);
    const controller = createTopologyTransitionController({
        duration,
        reducedMotion,
    });
    let activeLayer = currentLayer;
    let stagingLayer = incomingLayer;
    let currentDataset = null;
    let generation = 0;
    function renderDataset(dataset) {
        const frame = prepareTopologyRenderFrame({
            cells,
            occupants: dataset.nodes,
            relationships: dataset.relationships ?? [],
        });
        return renderTopologyGridMarkup({
            frame,
            radius,
            showNodes: true,
            connectorRouting: dataset.connectorRouting ?? connectorRouting,
            className: "topology-dataset-content",
        });
    }
    async function transition(dataset) {
        const transitionGeneration = ++generation;
        appendRenderedContent(stagingLayer, renderDataset(dataset));
        stagingLayer.style.opacity = "0";
        stagingLayer.style.pointerEvents = "none";
        await controller.run({
            outgoing: { element: activeLayer },
            incoming: { element: stagingLayer },
        });
        if (transitionGeneration !== generation)
            return;
        clearLayer(activeLayer);
        activeLayer.style.opacity = "0";
        activeLayer.style.pointerEvents = "none";
        stagingLayer.style.opacity = "1";
        stagingLayer.style.pointerEvents = "auto";
        const previousActive = activeLayer;
        activeLayer = stagingLayer;
        stagingLayer = previousActive;
        currentDataset = dataset;
    }
    return {
        getCurrentDataset() {
            return currentDataset;
        },
        transition,
        cancel() {
            generation += 1;
            controller.cancel();
        },
        destroy() {
            generation += 1;
            controller.cancel();
            clearLayer(activeLayer);
            clearLayer(stagingLayer);
            activeLayer.remove();
            stagingLayer.remove();
        },
    };
}
